const base = env.get("HA_URL");
const token = env.get("HA_TOKEN");
const entity = env.get("ALEXA_ENTITY");
if (!base || !token || !entity) {
    node.error("Set HA_URL, HA_TOKEN and ALEXA_ENTITY before sending a question.");
    return null;
}
msg.method = "POST";
msg.url = base.replace(/\/+$/, "") + "/api/services/script/activate_alexa_actionable_notification";
msg.headers = {"Authorization": "Bearer " + token, "Content-Type": "application/json"};
msg.payload = {text: "Did the Node-RED question work?", event_id: "node_red_test",
               alexa_device: entity, suppress_confirmation: false};
return msg;
